-- D-30: issue FSQM-032 Chemical Control Program and FRM-402 Chemical Register; move the SDS set onto
-- FSQM-032; archive the separate "Chemical Safety Data Sheets (SDS)" reference document; SOP-2.3.2 v3.
--
-- Owner, 2026-09-22: "issue D-30 with the SDS moved".
--
-- FSQM-032, FRM-402: active, GJM, 2026-09-22, revision New (first issue). FSQM-032 takes four of the old
-- document's five attachments as its own (same storage paths - nothing re-uploaded); the green dish
-- liquid's sheet is left behind because it is no longer used. Its three references to the old document
-- and FRM-402's one now point at FSQM-032.
--
-- SOP-2.3.2 v2 -> v3: it named the old document as where a chemical's specification (its SDS) is kept -
-- archiving the document without revising it would leave an active SOP pointing at nothing.
-- SOP-906 and FSQM-012 mention it only in their revision history, which is left as written.
--
-- FRM-402 already holds one DRAFT entry (GJM, 2026-09-22), left untouched; only a submitted entry
-- would stop this.
--
-- The old document goes to 'archived' (soft delete, never hard). Every row is guarded on its md5.

begin;

do $guard$
declare h text; st text; rev text;
begin
  select md5(content::text), status into h, st from public.sop_documents where sop_number = 'FSQM-032';
  if st is distinct from 'draft' or h <> '22f3a559ae19c23e92850a55ccc42bd5' then raise exception 'FSQM-032 is % or changed since review (md5 %).', st, h; end if;
  select md5(content::text), status into h, st from public.sop_documents where sop_number = 'FRM-402';
  if st is distinct from 'draft' or h <> '5df3d089f05480cce8ab7987dcb1bd1d' then raise exception 'FRM-402 is % or changed since review (md5 %).', st, h; end if;
  select md5(content::text), status, revision into h, st, rev from public.sop_documents where sop_number = 'SOP-2.3.2';
  if (st, rev) is distinct from ('active', 'v2') or h <> '5e36c5114b644e1678c8f4672fc13b72' then
    raise exception 'SOP-2.3.2 is %/% or changed since this migration was written (md5 %).', st, rev, h;
  end if;
  select md5(content::text), status into h, st from public.sop_documents where id = '32ec973c-d771-4eca-91cc-7d836bf2cd32';
  if st is distinct from 'active' or h <> 'ccda3bbe84168c640254696bfb235f1d' then raise exception 'SDS document is % or changed (md5 %).', st, h; end if;
  if (select count(*) from public.sop_document_responses r join public.sop_documents d on d.id = r.document_id
       where d.sop_number = 'FRM-402' and r.status <> 'draft') <> 0 then
    raise exception 'FRM-402 has SUBMITTED entries before issue - check them first.';
  end if;
end $guard$;

update public.sop_documents
   set content = $j${"scope": "Every detergent, sanitizer, cleaner and rinse additive on site, and the food-grade lubricants. No pesticides are kept on site; the pest control contractor brings and removes them.", "purpose": "This program states how Adventure Bakery controls the chemicals it uses, so that they cannot contaminate product, packaging or product-contact surfaces and the people who handle them are protected: which chemicals are approved, how they are labelled, stored, mixed and used, and what happens with spills and disposal.", "records": "• FRM-402 entries - the latest submitted entry is the register in force\n• The SDS attached to this program, and the printed binder\n• FRM-903 daily mixing checks\n• FRM-952 training records for chemical handlers", "procedure": ["Approved chemicals", "• Only chemicals on the FRM-402 register are brought on site or used (SQF 11.2.5.2, 11.6.4.1).", "• A new chemical is approved by the SQF Practitioner before it is bought: its SDS is attached to this program, its label is read for use and dilution, and a new FRM-402 entry adds it.", "• The register is re-issued at least once a year, and whenever a chemical is added, changed or removed.", "• No pesticides, rodenticides or insecticides are kept on site. If that changes, they are kept in their own locked space, apart from sanitizers and detergents (SQF 11.6.4.2).", "SDS and labels", "• Every SDS is attached to this program in the Team Portal, under its Reference Documents, which all staff can open, and a printed copy is kept in a binder beside the chemical store.", "• Chemicals stay in their original, labelled containers. A working container is labelled with the product name and dilution when it is filled, and is used only for that product (SQF 11.6.4.1, 11.2.5.3).", "• A container with a missing or unreadable label is not used; its contents are disposed of under Part 8.", "The chemical store", "• Chemicals are kept in the chemical locker: lockable, signed Chemical Storage - Authorised Staff Only, ventilated, and away from ingredients, packaging, utensils and product-contact surfaces - never above them (SQF 11.6.4.2).", "• The locker is kept locked when nobody is taking chemicals from it. Only trained Production staff and the Management team open it.", "• Nothing else is kept in it: no utensils, packaging, food or clothing. Food-grade lubricants are kept on their own shelf.", "• During production, the day's working solutions of sanitizer and detergent may be kept at the sink and the washer, labelled; the washer's rinse additive stays connected. Concentrate goes back to the locker after each use, and working solutions are emptied at the end of the day (SQF 11.6.4.4).", "> THE LOCKER IS NOT YET INSTALLED. Chemicals are kept on their own shelf, away from food, but it does not lock. Until the locker is in place, 11.6.4.2 is not met, and FRM-402 records it as Not yet.", "Mixing and use", "• Every chemical is used only as its label says, at the dilution on the register (SQF 11.6.4.3). For Sani-512, an EPA-registered sanitizer, the label is the law.", "• Sani-512 is mixed at 1:512 and checked with a test strip at about 200 ppm; Dawn Professional is measured at 1-2 oz per 10 gallons. Both are recorded on FRM-903, and each machine's SSOP gives the steps (SQF 11.2.5.3).", "• Chemicals are never mixed with each other, and are never mixed or used over open product, ingredients or packaging.", "• A product-contact surface is touched only by the sanitizer at its label dilution, or by detergent that is rinsed off.", "PPE and first aid", "• Anyone mixing concentrate wears chemical-resistant gloves and safety glasses or goggles. The Sani-512 SDS says it causes severe skin burns and eye damage.", "• An eyewash station or eyewash bottles are kept within reach of the locker and the mixing point, and a first aid kit is kept on site (SQF 11.6.4.5).", "> GLOVES, EYE PROTECTION, EYEWASH AND A SPILL KIT ARE STILL TO BE BOUGHT. Until they are on site, 11.6.4.5 and 11.6.4.7 are not met, and FRM-402 records them as Not yet.", "Spills", "• Put on gloves and eye protection, and keep other people away.", "• Contain the spill with absorbent from the spill kit, scoop it into a bag, seal and label it, then wash the area with water.", "• Chemical on skin or in the eyes: rinse with water for at least 15 minutes, using the eyewash for eyes, and follow the SDS first aid section. Sani-512 in the eyes needs medical help.", "• If a spill reaches ingredients, packaging, product or a product-contact surface, they are held under FSQM-018, and the surface is cleaned and sanitized before use.", "• These instructions are posted beside the chemical locker, with the spill kit: absorbent, bags, a scoop, gloves and goggles (SQF 11.6.4.7).", "Training", "• Production staff who clean are the chemical handlers. Before handling chemicals, each is trained in what each chemical is for, its hazards, mixing and checking it, PPE, storage, spills and disposal (SQF 11.6.4.5).", "• The training is recorded on FRM-952.", "Disposal", "• Primary containers are never reused for anything (SQF 11.6.4.6).", "• Empty containers are rinsed as their label says - Sani-512 is triple-rinsed - bagged, and kept in the locker until the site's waste collection day. They then go out with the trash or recycling, collected by the site's waste collection service.", "• Unused, expired or unlabelled chemical is never poured into a drain unless its label allows it. It is disposed of as its SDS section 13 says, through a hazardous waste drop-off or back to the supplier."], "definitions": "Chemical register: the rows of the latest submitted FRM-402 entry.\nConcentrate: a chemical as supplied, before dilution.\nWorking container: a spray bottle or bucket holding a chemical diluted for use.", "responsibility": "SQF Practitioner - owns this program, approves every chemical before it is bought, and signs the register.\nManagement team - buys chemicals only from the register, and provides the locker, PPE, eyewash and spill kit.\nProduction staff - handle chemicals only after training under Part 7, mix and use them as their label and SSOP say, and return them to the locker.", "form_references": "FRM-402 - Chemical Register\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record (mixing checks)\nFRM-952 - Training Competency Verification Record\nFRM-913 - GMP / Food Safety Inspection Record (monthly check of the store, row 11.6.4)", "revision_history": "New - 2026-09-21 - DRAFT under D-30, for the nine Non-Compliant findings against 11.2.5.2, 11.2.5.3 and 11.6.4.\n\nWHAT THE SITE DOES NOW (owner, 2026-09-21): chemicals are kept separately but not locked, and a locker is planned; Production staff mix and handle them; there are no gloves, eye protection, eyewash or spill kit yet, and they are to be bought; empty containers are rinsed and put in the trash or recycling.\n\nThe program writes the locker, the PPE, the eyewash and the spill kit in as requirements and says plainly that they are not yet in place, so that the record shows the gap rather than hiding it.\n\nNO PESTICIDES ON SITE (owner, 2026-09-21): confirmed. The pest control contractor brings and removes them.\n\nGREEN DISHWASHING LIQUID (owner, 2026-09-21): no longer used, so it is not on the register. Any stock left on site is disposed of under Part 8.\n\nSDS MOVED HERE AT ISSUE (owner, 2026-09-22): the SDS set was held in a separate, unnumbered \"Chemical Safety Data Sheets (SDS)\" reference document, created 2026-08-25 before any chemical program existed. 11.6.4.1 asks the register to be supplemented with current SDS, so they now sit with the program that owns the register. Four SDS were moved: Sani-512, Dawn Professional, Keystone rinse additive, Mr. Clean degreaser. The green dishwashing liquid's sheet was not, because it is no longer used. The old document is archived, not deleted.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.2.5.2, 11.2.5.3 (detergents and sanitizers) and 11.6.4.1 to 11.6.4.7 (hazardous chemicals and toxic substances).\n29 CFR 1910.1200 - OSHA Hazard Communication Standard.\nFIFRA - Sani-512 is an EPA-registered product; its label is the legal instruction for use and disposal.\n\nThe machine SSOPs (SOP-901 to SOP-906) - mixing steps.\nFSQM-029 Preventive Maintenance Program - lubricants.\nFSQM-018 Non-Conforming Product and Equipment - product a spill may have affected.", "attachments": [{"name": "SANI512_SDS.pdf", "path": "32ec973c-d771-4eca-91cc-7d836bf2cd32/files/SANI512_SDS.pdf"}, {"name": "DAWN_PROFESSIONAL_SDS.pdf", "path": "32ec973c-d771-4eca-91cc-7d836bf2cd32/files/DAWN_PROFESSIONAL_SDS.pdf"}, {"name": "MR_CLEAN_PROFESSIONAL_DEGREASER_FLOOR_CLEANER_SDS.pdf", "path": "32ec973c-d771-4eca-91cc-7d836bf2cd32/files/MR_CLEAN_PROFESSIONAL_DEGREASER_FLOOR_CLEANER_SDS.pdf"}, {"name": "KEYSTONE_LIQUID_RINSE_ADDITIVE_SDS.pdf", "path": "32ec973c-d771-4eca-91cc-7d836bf2cd32/files/KEYSTONE_LIQUID_RINSE_ADDITIVE_SDS.pdf"}]}$j$::jsonb, status = 'active', approved_by = 'GJM', effective_date = date '2026-09-22'
 where sop_number = 'FSQM-032';

update public.sop_documents
   set content = $j${"form_schema": {"sections": [{"id": "about", "title": "1. How this record works", "fields": [{"id": "how_this_works", "text": "THE ROWS BELOW ARE THE APPROVED CHEMICAL REGISTER (SQF 11.2.5.2, 11.6.4.1). Only chemicals on it are brought on site or used.\n\nA NEW ENTRY is made when a chemical is added, changed or removed, and at least once a year. The latest submitted entry is the register in force.\n\nBEFORE A CHEMICAL IS ADDED, its SDS is attached to FSQM-032 and its label is read for use and dilution. Delete a row only when the chemical has left the site.", "type": "info", "label": "The approved chemical register"}]}, {"id": "register", "title": "2. Register", "fields": [{"id": "review_date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true, "defaultToday": true}, {"id": "reason", "type": "select", "label": "Reason for this entry", "width": "third", "options": ["First issue", "Annual review", "Chemical added", "Chemical changed or removed"], "required": true, "showInList": true}, {"id": "chemicals", "rows": {"mode": "fixed", "labels": ["Noble Sani-512 sanitizer", "Dawn Professional Dish Detergent", "Keystone liquid rinse additive", "Mr. Clean Professional Degreaser Floor Cleaner", "NSF H1 food-grade oil", "Beldos food-approved grease"], "addLabel": "Add chemical", "guidance": ["• EPA reg. 6836-266-65239. The label is the legal instruction for use (FIFRA).\n• Concentrate: gloves and eye protection when mixing. Checked with a test strip at about 200 ppm and recorded on FRM-903.", "• Measured dose, recorded on FRM-903.", "• Connected to the washer (SOP-905). A spare container is kept in the chemical locker, not beside the washer.", "• Floors only - never on product-contact surfaces.", "• Record the product name and supplier, and file its SDS.\n• Lubricants are covered by FSQM-029 Part 7.", "• File its SDS.\n• Lubricants are covered by FSQM-029 Part 7."], "deletable": true, "labelHeader": "Chemical", "defaultValues": [{"sds": "Yes", "type": "Sanitizer", "hazard": "DANGER - corrosive, causes eye damage; store locked up", "kept_in": "Chemical locker", "dilution": "1:512 (1 fl oz per 4 gal, about 200 ppm) for food contact; 1:160 for the foot bath", "supplier": "Noble Chemical", "used_for": "Sanitizing food-contact surfaces, no rinse; foot bath"}, {"sds": "Yes", "type": "Detergent", "hazard": "WARNING - eye irritant", "kept_in": "Chemical locker", "dilution": "1-2 oz per 10 gal", "supplier": "Procter & Gamble Professional", "used_for": "Manual washing of ware and equipment parts"}, {"sds": "Yes", "type": "Rinse additive", "hazard": "See SDS", "kept_in": "At the pot and pan washer (daily-use supply)", "dilution": "Dosed by the washer", "supplier": "Keystone", "used_for": "Pot and pan washer final rinse"}, {"sds": "Yes", "type": "Cleaner", "hazard": "See SDS", "kept_in": "Chemical locker", "dilution": "As the label says", "supplier": "Procter & Gamble Professional", "used_for": "Floors"}, {"sds": "No - obtain", "type": "Food-grade lubricant", "hazard": "Food-grade (H1)", "kept_in": "Kept apart from the cleaning chemicals", "dilution": "Neat, a few drops", "supplier": "", "used_for": "Kook-E-King feed-roller bushings (SOP-502)"}, {"sds": "No - obtain", "type": "Food-grade lubricant", "hazard": "Food-grade", "kept_in": "Kept apart from the cleaning chemicals", "dilution": "Neat, thin film", "supplier": "Beldos", "used_for": "Beldos 275 seals and O-rings (SOP-503)"}]}, "type": "grid", "label": "Approved chemicals", "columns": [{"id": "type", "type": "select", "label": "Type", "options": ["Sanitizer", "Detergent", "Rinse additive", "Cleaner", "Food-grade lubricant", "Other"]}, {"id": "supplier", "type": "text", "label": "Supplier"}, {"id": "used_for", "type": "text", "label": "Used for", "width": 2}, {"id": "dilution", "type": "text", "label": "Dilution", "width": 2}, {"id": "hazard", "type": "text", "label": "Main hazard (SDS)", "width": 2}, {"id": "kept_in", "type": "text", "label": "Kept in"}, {"id": "sds", "type": "select", "label": "SDS on file", "options": ["Yes", "No - obtain"], "required": true}], "rowDialog": true}]}, {"id": "store", "title": "3. Store and safety equipment", "fields": [{"id": "store_info", "text": "\"Not yet\" is an honest answer and is expected until the purchases in FSQM-032 are made.", "type": "info", "label": "Answer as things are today"}, {"id": "locker", "type": "select", "label": "Chemical locker installed, signed and locked", "width": "half", "options": ["Yes", "Not yet"], "required": true}, {"id": "ppe", "type": "select", "label": "Chemical gloves and eye protection available", "width": "half", "options": ["Yes", "Not yet"], "required": true}, {"id": "eyewash", "type": "select", "label": "Eyewash within reach of the locker and mixing point", "width": "half", "options": ["Yes", "Not yet"], "required": true}, {"id": "spill_kit", "type": "select", "label": "Spill kit and posted spill instructions", "width": "half", "options": ["Yes", "Not yet"], "required": true}, {"id": "sds_binder", "type": "select", "label": "Printed SDS binder beside the store", "width": "half", "options": ["Yes", "Not yet"], "required": true}, {"id": "store_notes", "type": "textarea", "label": "Notes"}, {"id": "prepared_by", "role": "filler", "type": "signature", "label": "Prepared by", "required": true, "statement": "This register lists every chemical on site, as checked on the date shown."}, {"id": "approved_by", "role": "verifier", "type": "signature", "label": "Approved by the SQF Practitioner", "required": true, "statement": "I approve the chemicals on this register for use on site."}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": false, "requireVerification": true, "instanceTitleTemplate": "Chemical register - {review_date}"}, "schemaVersion": 1}}$j$::jsonb, status = 'active', approved_by = 'GJM', effective_date = date '2026-09-22'
 where sop_number = 'FRM-402';

update public.sop_documents
   set content = $j${"scope": "All ingredients, additives, flavourings, processing aids and packaging used in production, and the cleaning and sanitising chemicals used on food-contact surfaces. Finished product specifications are developed under SOP-2.3.1, and contract service specifications are held on FRM-206. Equipment and utensil specifications, and potable water, are outside this procedure.", "purpose": "To define how specifications for raw materials, packaging, processing aids and chemicals are developed, approved, validated and kept current, and how those materials are received and controlled, so that only material fit for its intended use goes into the baked product.", "records": "• FRM-207 entries, each with its specification sheet or allergen statement, the photo of the pack, the food-contact packaging certificate where one applies, and superseded sheets kept beside the current one\n• SDS attached to FSQM-032 Chemical Control Program\n• REP-201 Approved Supplier Register and FRM-202 entries\n• FRM-301 receiving records and FRM-702 hold records\n• FRM-204 annual supplier evaluations and FRM-205 SCARs", "procedure": ["Every material that can affect the safety of the baked product has a specification, recorded as one entry on FRM-207 Material Specification Register before the material is first used.", "• This covers ingredients, additives and flavourings, processing aids, packaging, and the cleaning and sanitising chemicals used on food-contact surfaces.", "• An entry is one material as approved: a named product from a named manufacturer, with the manufacturer's specification sheet or allergen statement attached and the ingredient and Contains statements transcribed word for word. Where the manufacturer issues no specification, as for some commodity items, the entry records what the site specifies instead.", "• For a chemical, the specification is its Safety Data Sheet, attached to FSQM-032 Chemical Control Program; its FRM-207 entry says so.", "> FRM-207 lists the material, packaging, processing-aid and chemical specifications, FRM-206 lists the contract service specifications, and finished product specifications are controlled documents approved under SOP-2.3.1. Together they are the site's list of specifications (SQF 2.3.2.10).", "A new material is validated before its first use. The SQF Practitioner confirms each of the following, and records it by signing the FRM-207 entry:", "• it is bought from a supplier approved on FRM-202;", "• it is a food-grade product intended for the use it will be put to, and labelled for sale in the United States;", "• its allergens are known from its Contains statement, and any allergen it would add to a product is on that product's allergen statement before the material is used;", "• for packaging that touches food, the certificate in step 4 is attached.", "> A material that changes a product's formula is also trialled under SOP-2.3.1 before production use. Materials already in use when this revision was issued are entered on FRM-207 as each is next received.", "Suppliers are required to notify the site of any change in a material's composition that could affect the product: allergens above all, and moisture, protein or contaminant levels that vary by crop or season. The request is made in writing when the supplier is approved on FRM-202, and recorded on each FRM-207 entry.", "• A distributor rarely hears of a manufacturer's reformulation before the pack changes, so the pack is checked as well. A pack that looks different at receipt, with a new design, \"new recipe\" or a changed Contains statement, is compared with its FRM-207 entry before use. A changed allergen declaration is held for the SQF Practitioner's review.", "Packaging that comes into direct contact with food is used only with a letter of guarantee, certificate of conformance or regulatory certificate stating that it meets FDA food-contact requirements, attached to its FRM-207 entry.", "• If the supplier cannot provide one, the packaging is not used until one is obtained, or until the SQF Practitioner has had migration testing done by an accredited laboratory and has attached the result.", "Specifications are kept current. Each FRM-207 entry is reviewed at least annually, by its Next review date, and whenever the manufacturer issues a new sheet, the product or its allergens change, a different brand is bought, or a supplier notifies a change.", "• The review is recorded on the entry: the SQF Practitioner updates it, signs and dates it again, and sets the next review date. A replaced specification sheet stays attached beside the new one, so the entry shows what was specified before.", "• A material no longer used is marked Discontinued, never deleted.", "Deliveries are received and inspected on FRM-301 under SOP-2.3.4, against the approved brand on FRM-207. A distributor does not issue a certificate of analysis for each lot; the manufacturer's specification on FRM-207 and the checks recorded on FRM-301 for every delivery take its place.", "Material that fails its receiving check is tagged HOLD – DO NOT USE on FRM-702 and dispositioned under FSQM-018. Approved material is stored so that it cannot be contaminated or deteriorate.", "Supplier performance is reviewed annually on FRM-204, and a supplier non-conformance is raised on FRM-205."], "definitions": "", "responsibility": "The SQF Practitioner develops, approves and keeps current every material specification on FRM-207, validates each new material before its first use, asks suppliers to notify changes in composition, obtains the certificate for food-contact packaging, and approves finished product specifications under SOP-2.3.1.\nProduction staff receive and inspect each delivery on FRM-301 against the approved brand, and hold any material that fails, or whose pack has changed, for the SQF Practitioner.", "form_references": "FRM-207 - Material Specification Register (one entry per material: specification, allergens, validation, review)\nFRM-202 - Supplier Approval & Evaluation Record, and REP-201 - Approved Supplier Register\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-204 - Annual Supplier Performance Evaluation Checklist\nFRM-205 - Supplier Non-Conformance & Corrective Action Report (SCAR)\nFRM-206 - Contract Services Register (contract service specifications)\nSOP-2.3.1 - New Product and Specification Process (finished product specifications, formula trials)\nSOP-2.3.4 - Vendor Approval (supplier approval, receiving, brand substitution)\nFSQM-018 - Non-Conforming Product and Equipment", "revision_history": "v2 — 2026-09-21 — Specification control, under D-09.\n\nSix Minor findings against the specification clauses: 2.3.2.1 (no method or responsibility for specifications), 2.3.2.2 (no specifications), 2.3.2.4 (no validation of materials as fit for purpose), 2.3.2.5 (suppliers not required to notify composition changes), 2.3.2.6 (no certificate for food-contact packaging) and 2.3.2.10 (no review of specifications and no list of them).\n\nTHE PROCEDURE WAS REWRITTEN, NOT EXTENDED, because v1 contradicted documents issued since. It required a certificate of analysis for every lot, which the distributors Adventure Bakery buys through do not issue; SOP-2.3.4 v4 and FSQM-014 already say that, and say what takes its place. It excluded cleaning chemicals, which 2.3.2.2 names. Its roles (QA, Quality Leader) are posts the site does not have; one person holds the SQF Practitioner role and approves every specification.\n\nTHE REGISTER IS THE LIST. FRM-207 was issued on 2026-09-18 as one entry per material, approved as a named product from a named manufacturer. This revision makes it the record of every step the clauses ask for: the specification (2.3.2.2), the validation before first use (2.3.2.4, the SQF Practitioner's signature), the change-notification request (2.3.2.5), the packaging certificate (2.3.2.6) and the review (2.3.2.10). No new form was needed.\n\nA DISTRIBUTOR CANNOT PASS ON WHAT IT DOES NOT KNOW. Asking Sysco or Restaurant Depot to report a manufacturer's reformulation is what 2.3.2.5 requires, and it is done, but a distributor usually learns of a change when the pack changes. So the pack is also checked at receipt, and a changed allergen declaration is held.\n\nEquipment and utensil specifications (11.1.7.1) are left to their own procedure.\n\nv3 — 2026-09-22 — Chemical SDS now held on FSQM-032 Chemical Control Program, issued the same day; the separate Chemical Safety Data Sheets reference document is archived. Two references updated (procedure and records). Nothing else changes.", "governing_reference": ""}$j$::jsonb, revision = 'v3', effective_date = date '2026-09-22', approved_by = 'GJM'
 where sop_number = 'SOP-2.3.2';

update public.sop_documents set status = 'archived' where id = '32ec973c-d771-4eca-91cc-7d836bf2cd32';

do $verify$
declare c jsonb;
begin
  if (select count(*) from public.sop_documents where sop_number in ('FSQM-032', 'FRM-402') and status = 'active'
        and approved_by = 'GJM' and effective_date = date '2026-09-22' and revision = 'New') <> 2 then
    raise exception 'FSQM-032 / FRM-402 did not both issue.';
  end if;
  select content into c from public.sop_documents where sop_number = 'FSQM-032';
  if jsonb_array_length(c->'attachments') <> 4 or c::text like '%Chemical Safety Data Sheets document%'
     or (c->'attachments')::text like '%GREEN\_DISH%' then
    raise exception 'FSQM-032 SDS not moved cleanly.';
  end if;
  if (select content::text from public.sop_documents where sop_number = 'FRM-402') like '%Chemical Safety Data Sheets%' then
    raise exception 'FRM-402 still names the old document.';
  end if;
  if (select count(*) from public.sop_documents where sop_number = 'SOP-2.3.2' and revision = 'v3' and status = 'active'
        and content->>'records' like '%FSQM-032%' and content->'procedure'->>3 like '%FSQM-032%') <> 1 then
    raise exception 'SOP-2.3.2 v3 not applied.';
  end if;
  if (select status from public.sop_documents where id = '32ec973c-d771-4eca-91cc-7d836bf2cd32') <> 'archived' then
    raise exception 'SDS document not archived.';
  end if;
  if exists (select 1 from public.sop_documents where status = 'active'
               and (content->'procedure')::text || coalesce(content->>'records', '') like '%Chemical Safety Data Sheets%') then
    raise exception 'an active procedure or records section still names the old document.';
  end if;
end $verify$;

commit;
